import os
from datetime import datetime
import logging
import warnings


class LogManager:
    def __init__(self):
        self.log_dir = None
        self.tstamp_format = "%H%M%S_%Y-%m-%d"
        self.logger = None

    def setup(self, alias, log_dir, rmod_type, serial_number, class_name, log_to_console):
        self.log_dir = log_dir
        if self.logger is not None:
            self.logger.warning(f"[{alias}] Logger already initialized.")
            for handler in self.logger.logger.handlers[:]:
                if isinstance(handler, logging.FileHandler):
                    self.logger.logger.removeHandler(handler)
                    handler.close()
        self.logger, rmod_log_dir, log_prefix = self._get_logger(
            alias, rmod_type, serial_number, class_name, log_to_console
        )
        return self.logger, rmod_log_dir, log_prefix

    @staticmethod
    def create_new_log_directory(log_dir: str):
        if not os.path.isdir(log_dir):
            try:
                os.makedirs(os.path.normpath(log_dir), exist_ok=True)
            except OSError:
                warnings.warn(message=f"Cannot create {log_dir} log directory.")
                return None
        return log_dir

    def _get_logger(self, alias, rmod_type, serial_number, class_name, log_to_console):
        if not os.path.isdir(self.log_dir):
            warnings.warn(
                message=f"[{alias}] Cannot initialize directory and logger"
                " because main log directory does not exist."
            )
            return None, None

        curr_time = datetime.now().strftime(self.tstamp_format)
        log_prefix = f"{rmod_type}_{serial_number}_{alias}"
        rmod_log_dir = self._create_log_directory(log_prefix, curr_time, alias)

        extra = {"rmod_type": rmod_type, "serial_number": serial_number}

        self._setup_temp_logger_and_log_initialization_to_the_console(alias, extra)

        logger = self._setup_main_logger(
            alias, serial_number, curr_time, class_name, rmod_log_dir, extra, log_to_console
        )

        return logger, rmod_log_dir, log_prefix

    def _create_log_directory(self, log_prefix, curr_time, alias):
        rmod_log_dir = os.path.normpath(os.path.join(self.log_dir, f"{log_prefix}_{curr_time}_serial_logs"))
        try:
            os.makedirs(rmod_log_dir, exist_ok=True)
        except OSError:
            warnings.warn(
                message=f"[{alias}] Cannot create directory under {rmod_log_dir}. "
                f"Logs will be saved in {self.log_dir}"
            )
            rmod_log_dir = self.log_dir
        return rmod_log_dir

    def _setup_temp_logger_and_log_initialization_to_the_console(self, alias, extra):
        temp_logger = logging.getLogger("temp_console_logger")
        temp_logger.setLevel(logging.INFO)
        console_handler = logging.StreamHandler()
        console_formatter = logging.Formatter(
            fmt="%(asctime)s.%(msecs)03d [%(rmod_type)s:%(serial_number)s] [%(levelname)s] %(message)s",
            datefmt="%d-%b-%y %H:%M:%S",
        )
        console_handler.setFormatter(console_formatter)
        temp_logger.addHandler(console_handler)
        temp_logger = logging.LoggerAdapter(temp_logger, extra)
        temp_logger.info(f"Connecting to RMOD with alias '{alias}'")
        console_handler.flush()
        temp_logger.logger.removeHandler(console_handler)

    def _setup_main_logger(self, alias, serial_number, curr_time, class_name, rmod_log_dir, extra, log_to_console):
        formatter = logging.Formatter(
            fmt="%(asctime)s.%(msecs)03d [%(rmod_type)s:%(serial_number)s] [%(levelname)s] %(message)s",
            datefmt="%d-%b-%y %H:%M:%S",
        )
        file_handler = logging.FileHandler(os.path.join(rmod_log_dir, f"{class_name}_control.log"), mode="w")
        file_handler.setFormatter(formatter)

        main_logger = logging.getLogger(f"{alias}_{serial_number}_{curr_time}")
        main_logger.setLevel(logging.DEBUG)
        main_logger.addHandler(file_handler)

        if log_to_console:
            console_handler = logging.StreamHandler()
            console_handler.setFormatter(formatter)
            console_handler.setLevel(logging.DEBUG)
            main_logger.addHandler(console_handler)

        return logging.LoggerAdapter(main_logger, extra)
